// The registry row travels alongside the query result, so a metric that
// returns an unexpected shape fails loudly here instead of silently
// poisoning the baseline with a NaN.
const registry = $('Load Metric Registry').item.json;
const row = $json;

if (row.error) {
  return { json: {
    metric_key: registry.metric_key,
    unit: registry.unit || '',
    value: null,
    collection_error: String(row.error),
  } };
}

const candidate = row.value !== undefined ? row.value : Object.values(row)[0];
const value = Number(candidate);

return { json: {
  metric_key: registry.metric_key,
  unit: registry.unit || '',
  value: Number.isFinite(value) ? value : null,
  collection_error: Number.isFinite(value)
    ? null
    : `Metric SQL returned a non-numeric value: ${JSON.stringify(row).slice(0, 200)}`,
} };

// A baseline built on nine days of history is not a baseline. Detection
// refuses to score those metrics, so surface them here instead of letting
// them sit silently unmonitored.
const MIN_OBS = 14;
const rows = $input.all().map(i => i.json);

const thin = rows.filter(r => Number(r.n_obs) < MIN_OBS);
const flat = rows.filter(r => Number(r.mad) === 0);

return [{ json: {
  metrics_total: rows.length,
  metrics_ready: rows.length - thin.length,
  thin_count: thin.length,
  thin_metrics: thin.map(r => `${r.metric_key} (${r.n_obs}/${MIN_OBS} days)`),
  flat_metrics: flat.map(r => r.metric_key),
  min_observations: MIN_OBS,
  computed_at: new Date().toISOString(),
} }];

// This node, and only this node, decides what counts as an anomaly.
// It is deterministic and auditable. The model downstream can explain a
// flagged metric, argue it is a false positive, or fail entirely, and none
// of that changes the numbers computed here.
const settings = $('Detection Settings').first().json;
const MIN_OBS = Number(settings.min_observations) || 14;

// 0.6745 puts a median-absolute-deviation score on the same scale as a
// standard-deviation score, so a threshold of 3 still means what people
// expect it to mean.
const MAD_TO_SIGMA = 0.6745;

const isoDow = (d) => {
  const day = new Date(String(d).slice(0, 10) + 'T00:00:00Z').getUTCDay();
  return day === 0 ? 7 : day;
};

return $input.all().map((item) => {
  const r = item.json;
  const value = Number(r.value);
  const nObs = Number(r.n_obs) || 0;
  const madRaw = Number(r.mad) || 0;
  const stdev = Number(r.stdev_value) || 0;
  const threshold = Number(r.z_threshold) || 3;
  const minAbs = Number(r.min_abs_change) || 0;
  const direction = r.direction || 'both';

  // Prefer the day-of-week median where we have one. Weekly seasonality is
  // the biggest source of false positives on business metrics: Saturday
  // signups are not an incident.
  const dowMap = r.dow_medians || {};
  const dowMedian = Number(dowMap[String(isoDow(r.observed_on))]);
  const usedDow = Number.isFinite(dowMedian) && nObs >= 21;
  const baseline = usedDow ? dowMedian : Number(r.median_value);

  const absChange = value - baseline;
  const pctChange = baseline !== 0 ? (absChange / Math.abs(baseline)) * 100 : null;

  // MAD of zero means a perfectly flat series. Fall back to sample stdev
  // rather than dividing by zero and calling every wobble a 10-sigma event.
  let z = null;
  let scale = 'mad';
  if (madRaw > 0) {
    z = (MAD_TO_SIGMA * absChange) / madRaw;
  } else if (stdev > 0) {
    z = absChange / stdev;
    scale = 'stdev';
  } else {
    scale = 'none';
  }

  const base = {
    ...r, value, baseline_value: baseline, used_dow_baseline: usedDow,
    abs_change: absChange, pct_change: pctChange, z_score: z, scale,
  };
  const skip = (reason) => ({ json: {
    ...base, is_anomaly: false, severity: 'none', skip_reason: reason } });

  if (nObs < MIN_OBS) return skip('only ' + nObs + ' of ' + MIN_OBS + ' baseline days');
  if (z === null) return skip('series has no dispersion to score against');
  if (Math.abs(absChange) < minAbs) {
    return skip('change ' + absChange.toFixed(2) + ' below floor ' + minAbs);
  }
  if (direction === 'drop' && absChange >= 0) return skip('metric rose, only drops alert');
  if (direction === 'rise' && absChange <= 0) return skip('metric fell, only rises alert');
  if (Math.abs(z) < threshold) {
    return skip('z ' + z.toFixed(2) + ' below threshold ' + threshold);
  }

  const magnitude = Math.abs(z);
  const severity = magnitude >= threshold * 2 ? 'critical'
                 : magnitude >= threshold * 1.4 ? 'warning'
                 : 'info';

  return { json: { ...base, is_anomaly: true, severity, skip_reason: null } };
});

// Two jobs: stop re-alerting on a drift that is already someone's problem,
// and cap how many investigations one run can start. A warehouse-wide outage
// trips every metric at once. Without the cap that is one agent run per
// metric, all reaching the same conclusion, all billed.
const settings = $('Detection Settings').first().json;
const COOLDOWN_HOURS = Number(settings.cooldown_hours) || 24;
const MAX_PER_RUN = Number(settings.max_incidents_per_run) || 10;

const anomalies = $('Keep Only Anomalies').all().map(i => i.json);
const openRows = $('Fetch Open Incidents').all()
  .map(i => i.json)
  .filter(r => r && r.metric_key);

const openBy = {};
for (const row of openRows) openBy[row.metric_key] = row;

// Loudest first, so if the cap bites it keeps the incidents that matter.
const ranked = anomalies.slice().sort(
  (a, b) => Math.abs(Number(b.z_score)) - Math.abs(Number(a.z_score))
);

let admitted = 0;
return ranked.map((r) => {
  const open = openBy[r.metric_key];
  let suppressed = false;
  let reason = null;

  if (open) {
    const hours = (Date.now() - new Date(open.last_opened_at).getTime()) / 3600000;
    if (hours < COOLDOWN_HOURS) {
      suppressed = true;
      reason = 'open incident on this metric ' + hours.toFixed(1)
             + 'h ago, cooldown is ' + COOLDOWN_HOURS + 'h';
    }
  }

  if (!suppressed && admitted >= MAX_PER_RUN) {
    suppressed = true;
    reason = 'run cap of ' + MAX_PER_RUN + ' incidents reached, ranked #'
           + (admitted + 1) + ' by absolute z-score';
  }

  if (!suppressed) admitted += 1;

  return { json: { ...r, suppressed, suppression_reason: reason,
                   detected_at: new Date().toISOString() } };
});

