{
  "type": "object",
  "properties": {
    "primary_hypothesis": {
      "type": "string",
      "description": "One paragraph. What most likely caused this move, stated so a data engineer can act on it."
    },
    "hypothesis_class": {
      "type": "string",
      "enum": ["data_pipeline", "product_change", "seasonality", "external",
               "measurement_artifact", "genuine_business_change", "unknown"],
      "description": "Use unknown when the tools did not give you enough to choose."
    },
    "evidence": {
      "type": "array",
      "description": "Every entry must come from a tool call you actually made. Two entries minimum.",
      "items": {
        "type": "object",
        "properties": {
          "tool": {"type": "string", "description": "Which tool produced this"},
          "finding": {"type": "string", "description": "The concrete number, row, or title you saw"},
          "supports": {"type": "string", "enum": ["for", "against"]}
        },
        "required": ["tool", "finding", "supports"]
      }
    },
    "alternative_hypotheses": {
      "type": "array",
      "items": {"type": "string"},
      "description": "Explanations you considered and could not rule out"
    },
    "referenced_metric_keys": {
      "type": "array",
      "items": {"type": "string"},
      "description": "Every metric_key you named anywhere in this response"
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. Confidence in the primary hypothesis given the evidence, not in your writing."
    },
    "is_likely_false_positive": {
      "type": "boolean",
      "description": "True if the move looks like a measurement artefact rather than a real change"
    },
    "recommended_next_step": {
      "type": "string",
      "description": "The single next thing a human should check. Be specific."
    }
  },
  "required": ["primary_hypothesis", "hypothesis_class", "evidence",
               "alternative_hypotheses", "referenced_metric_keys", "confidence",
               "is_likely_false_positive", "recommended_next_step"]
}

