// The agent cannot be trusted to mark its own homework, so this checks the
// shape of what it returned against what the detector already knows. A
// hypothesis that cites a metric nobody has ever collected is the classic
// confabulation, and it is cheap to catch here.
const out = $json.output || $json;
const incident = $('Open Incident Record').item.json;
const detected = $('Suppress Duplicates').item.json;

const knownKeys = new Set(
  $('Fetch Latest Vs Baseline').all().map(i => i.json.metric_key)
);

const evidence = Array.isArray(out.evidence) ? out.evidence : [];
const usable = evidence.filter(
  e => e && typeof e.finding === 'string' && e.finding.trim().length >= 12
);
const referenced = Array.isArray(out.referenced_metric_keys)
  ? out.referenced_metric_keys : [];
const fabricated = referenced.filter(k => k && !knownKeys.has(k));

const confidence = Number(out.confidence);

return [{ json: {
  incident_id: incident.id,
  metric_key: detected.metric_key,
  observed_on: detected.observed_on,
  observed_value: detected.value,
  baseline_value: detected.baseline_value,
  unit: detected.unit || '',
  z_score: detected.z_score,
  pct_change: detected.pct_change,
  severity: detected.severity,
  direction: detected.direction,
  owner_team: detected.owner_team,
  owner_email: detected.owner_email,
  owner_slack: detected.owner_slack,
  repo_owner: detected.repo_owner,
  repo_name: detected.repo_name,

  primary_hypothesis: out.primary_hypothesis || '',
  hypothesis_class: out.hypothesis_class || 'unknown',
  alternative_hypotheses: out.alternative_hypotheses || [],
  recommended_next_step: out.recommended_next_step || '',
  is_likely_false_positive: out.is_likely_false_positive === true,
  confidence: Number.isFinite(confidence) ? confidence : 0,
  evidence: usable,

  evidence_count: usable.length,
  has_counter_evidence: usable.some(e => e.supports === 'against'),
  fabricated_metric_keys: fabricated,
  fabricated_count: fabricated.length,
  investigation_failed: false,
} }];

