// Segment D is only as good as this input. Anything that is not one of the
// three dispositions is rejected rather than written, so precision numbers
// are never computed over junk.
const ALLOWED = ['confirmed', 'false_positive', 'wont_fix'];
const body = $json.body || $json;

const incidentId = Number(body.incident_id);
const disposition = String(body.disposition || '').toLowerCase().trim();
const note = String(body.note || '').slice(0, 1000);
const actor = String(body.actor || '').slice(0, 200);

const problems = [];
if (!Number.isInteger(incidentId) || incidentId <= 0) {
  problems.push('incident_id must be a positive integer');
}
if (!ALLOWED.includes(disposition)) {
  problems.push('disposition must be one of ' + ALLOWED.join(', '));
}

return [{ json: {
  incident_id: incidentId, disposition, note, actor,
  valid: problems.length === 0,
  problems,
} }];

// Thresholds set once and never revisited are how alerting dies: people
// stop reading the channel long before anyone admits the numbers are wrong.
// This turns human dispositions back into a concrete threshold suggestion.
const settings = $('Report Settings').first().json;
const MIN_SAMPLE = Number(settings.min_sample) || 5;

const rows = $input.all().map(i => i.json);

const scored = rows.map((r) => {
  const confirmed = Number(r.confirmed) || 0;
  const falsePositives = Number(r.false_positives) || 0;
  const judged = confirmed + falsePositives;
  const alerts = Number(r.alerts) || 0;
  const undispositioned = Number(r.undispositioned) || 0;

  const precision = judged > 0 ? confirmed / judged : null;
  const ignoreRate = alerts > 0 ? undispositioned / alerts : null;
  const threshold = Number(r.z_threshold) || 3;

  let recommendation = 'hold';
  let rationale = judged < MIN_SAMPLE
    ? 'only ' + judged + ' judged alert(s), not enough to move a threshold on'
    : 'precision looks acceptable';

  if (judged >= MIN_SAMPLE && precision !== null && precision < 0.5) {
    recommendation = 'raise to ' + (threshold + 0.5).toFixed(1);
    rationale = 'precision ' + (precision * 100).toFixed(0) + '% over ' + judged
              + ' judged alerts, most of what this metric reports is noise';
  } else if (judged >= MIN_SAMPLE && precision === 1 && Number(r.avg_abs_z) > threshold * 2) {
    recommendation = 'lower to ' + Math.max(2, threshold - 0.5).toFixed(1);
    rationale = 'every judged alert was real and the average was '
              + r.avg_abs_z + ' against a threshold of ' + threshold
              + ', so smaller genuine moves are probably going unreported';
  } else if (ignoreRate !== null && ignoreRate > 0.6 && alerts >= MIN_SAMPLE) {
    recommendation = 'review';
    rationale = (ignoreRate * 100).toFixed(0) + '% of alerts were never dispositioned, '
              + 'which usually means nobody is reading them';
  }

  return { ...r, precision, ignore_rate: ignoreRate, recommendation, rationale };
});

const judgedTotal = scored.reduce(
  (a, r) => a + (Number(r.confirmed) || 0) + (Number(r.false_positives) || 0), 0);
const confirmedTotal = scored.reduce((a, r) => a + (Number(r.confirmed) || 0), 0);

return [{ json: {
  window_days: Number(settings.window_days) || 30,
  metrics: scored,
  metrics_count: scored.length,
  alerts_total: scored.reduce((a, r) => a + (Number(r.alerts) || 0), 0),
  judged_total: judgedTotal,
  overall_precision: judgedTotal > 0 ? confirmedTotal / judgedTotal : null,
  actions: scored.filter(r => r.recommendation !== 'hold'),
} }];
